<?php
declare(strict_types=1);
require __DIR__.'/catalog.php';
header('Content-Type: text/html; charset=UTF-8');
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: strict-origin-when-cross-origin');
header("Content-Security-Policy: default-src 'self'; style-src 'self'; img-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'");
$sources=read_json(__DIR__.'/sources.json');
$view=param('view','home');
if (!in_array($view,['home','directory','sources','about','privacy','help'],true)) {http_response_code(404);$view='home';}
$q=substr(param('q'),0,200);
$country=param('country','HR'); if (!isset($sources[$country])) $country='HR';
$kind=param('kind'); if (!isset(TYPES[$kind])) $kind='';
$page=max(1,min(10000,(int)param('page','1')));
$error=false; $manifest=['count'=>0,'shards'=>[],'published_at'=>null]; $result=['records'=>[],'next'=>false];
try {
    $manifest=read_json(DATA.'/'.$country.'/manifest.json');
    if ($view==='directory') $result=search_catalog($manifest,$q,$country,$kind,$page);
} catch (Throwable $errorObject) { $error=true;http_response_code(503); }
$labels=['home'=>'Business data, clearly organized','directory'=>'Business directory','sources'=>'Official data sources','about'=>'About Crawlvora','privacy'=>'Privacy and corrections','help'=>'Search guide'];
?><!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($labels[$view])?> | Crawlvora</title><meta name="description" content="Explore published business entities, official registry sources and registration identifiers in the Crawlvora directory."><link rel="stylesheet" href="assets/site.css"><?php if ($view==='directory' && ($q!=='' || $page>1)): ?><meta name="robots" content="noindex,follow"><?php endif; ?></head>
<body><header><a class="brand" href="?view=home"><span class="mark">C</span><span>Crawlvora<small>BUSINESS DATA INTELLIGENCE</small></span></a><nav aria-label="Main navigation"><?php foreach (['directory'=>'Directory','sources'=>'Sources','about'=>'About','help'=>'Help'] as $key=>$label): ?><a href="<?=h(query_link(['view'=>$key]))?>"><?=h($label)?></a><?php endforeach; ?></nav></header>
<main><section class="hero"><p class="eyebrow">OFFICIAL SOURCES · TRANSPARENT COVERAGE</p><h1><?=h($labels[$view])?></h1><p>Research registered business entities by name or registration identifier. Discover companies, entrepreneurs, institutions and nonprofit organizations in a single catalog, with each published record linked to its official source.</p></section>
<?php if ($error): ?><p class="notice" role="alert">The catalog is temporarily unavailable. Please try again later.</p><?php endif; ?>
<?php if ($view==='home'||$view==='directory'): ?>
<section class="panel"><form action="index.php" method="get"><input type="hidden" name="view" value="directory"><label>Company name, OIB, MBS or registration number<input name="q" value="<?=h($q)?>" maxlength="200" placeholder="Search business entities"></label><div class="filters"><label>Country<select name="country"><?php foreach($sources as $code=>$source): ?><option value="<?=h($code)?>" <?=$code===$country?'selected':''?>><?=h($source['name'])?></option><?php endforeach; ?></select></label><label>Entity type<select name="kind"><option value="">All entity types</option><?php foreach(TYPES as $code=>$label): ?><option value="<?=h($code)?>" <?=$code===$kind?'selected':''?>><?=h($label)?></option><?php endforeach; ?></select></label><button type="submit">Search directory</button></div></form><p class="muted"><?=h((int)($manifest['count']??0))?> published records · <?php if (!empty($manifest['published_at'])): ?>Updated <?=h($manifest['published_at'])?><?php else: ?>No approved data snapshot published yet<?php endif; ?></p></section>
<?php if($view==='home'): ?><section class="grid"><?php foreach(TYPES as $code=>$label): if($code==='unknown')continue; ?><a class="panel category" href="<?=h(query_link(['view'=>'directory','kind'=>$code,'country'=>$country]))?>"><h2><?=h($label)?></h2><p>Browse published entities in this category, with official source attribution.</p><span>Explore directory →</span></a><?php endforeach; ?></section><section class="panel"><h2>Understand the organization behind a name</h2><p>Use official registration identifiers to distinguish similarly named organizations. Registration information can support supplier research, company verification and understanding the public sector. Always verify time-sensitive details with the source register before making a decision.</p><p>Crawlvora keeps published coverage explicit rather than estimating missing records or financial scores. Sources vary by country and available fields.</p><a href="?view=sources">Explore available official registers →</a></section>
<?php else: ?><section class="panel"><h2>Search results</h2><?php if(!$result['records']): ?><p>No matching published records. A missing entry does not mean the organization does not exist.</p><?php endif; ?><?php foreach($result['records'] as $record): ?><article class="record"><h3><?=h($record['name'])?></h3><p><?=h(TYPES[$record['kind']])?> · <?=h($sources[$record['country']]['name'])?><?php if(!empty($record['city'])): ?> · <?=h($record['city'])?><?php endif; ?></p><dl><dt>Registration number</dt><dd><?=h($record['registration_number']??'Not published')?></dd><dt>Tax identifier</dt><dd><?=h($record['tax_number']??'Not published')?></dd><dt>Source date</dt><dd><?=h($record['as_of'])?></dd></dl><a href="<?=h($sources[$record['country']]['url'])?>" rel="noopener noreferrer">Official register →</a></article><?php endforeach; ?><div class="pager"><?php if($page>1): ?><a href="<?=h(query_link(['view'=>'directory','q'=>$q,'country'=>$country,'kind'=>$kind,'page'=>$page-1]))?>← Previous</a><?php endif; ?><span>Page <?=h($page)?></span><?php if($result['next']): ?><a href="<?=h(query_link(['view'=>'directory','q'=>$q,'country'=>$country,'kind'=>$kind,'page'=>$page+1]))?>Next →</a><?php endif; ?></div></section><?php endif; ?>
<?php elseif($view==='sources'): ?><section class="grid"><?php foreach($sources as $source): ?><article class="panel"><h2><?=h($source['name'])?></h2><p><?=h($source['note'])?></p><p class="muted">Access: <?=h(str_replace('_',' ',$source['status']))?>. This is source availability, not confirmation of imported data.</p><a href="<?=h($source['url'])?>" rel="noopener noreferrer">Official source →</a></article><?php endforeach; ?></section>
<?php elseif($view==='about'): ?><section class="panel prose"><h2>One transparent catalog</h2><p>Crawlvora is designed to help users locate organizations through official business registers. Country and entity-type filters use explicit source classifications; unknown classifications remain unknown. The public website and local desktop workspace are separate: the website only receives reviewed publication snapshots.</p><h2>Data quality and limitations</h2><p>Records may be incomplete, historical or delayed. A public registry is not a credit report, a guarantee of solvency or a substitute for official documents. No unverified ownership connections, credit scores or financial statements are presented.</p></section>
<?php elseif($view==='privacy'): ?><section class="panel prose"><h2>Publication scope</h2><p>The catalog is intended for reviewed public organization records. Private workspace records, credentials, personal identification numbers of directors, private addresses and personal contacts must not be published. Source availability is distinct from permission to redistribute data.</p><h2>Corrections</h2><p>For a suspected source error, consult the official register linked beside the record. Before operating this website publicly, the operator must publish their identity, contact details, applicable privacy notice and correction request procedure.</p></section>
<?php else: ?><section class="panel prose"><h2>Search by name or identifier</h2><p>Enter a full or partial organization name, OIB, MBS or equivalent registration number. Country and entity-type filters narrow results. Numeric Croatian MBS values can be searched with or without leading zeros.</p><h2>Why some results may be missing</h2><p>Each country's published dataset has a different scope. The catalog only searches reviewed data snapshots currently installed on the website. If a result is missing, use the official register listed on the Sources page.</p></section><?php endif; ?>
</main><footer><span>Crawlvora · Business Data Intelligence</span><a href="?view=privacy">Privacy and corrections</a><a href="?view=sources">Data sources</a><a href="?view=help">Help</a></footer></body></html>
